'use strict';
const $ = id => document.getElementById(id);
const colors = {amber:'#e6b66c',cyan:'#6bc9c7',rose:'#e78e83',green:'#9bc87f'};
let state={version:1,worlds:[{id:crypto.randomUUID(),name:'My world',image:null,markers:[],mapVersion:2}]}, current, selected=null, pending=null, placing=false, scale=1, tx=0, ty=0, drag=null, imageURL=null, live=null, following=true, followInitialized=false;
const dbp=new Promise((resolve,reject)=>{const req=indexedDB.open('rupture-map',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
async function read(){const db=await dbp;return new Promise((resolve,reject)=>{const t=db.transaction('data');const r=t.objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function save(){const db=await dbp;return new Promise((resolve,reject)=>{const t=db.transaction('data','readwrite');t.objectStore('data').put(state,'state');t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
async function persist(){try{state.sharedKnown=SharedKnown.merge(state.sharedKnown,state.worlds);await save()}catch(e){alert('Could not save locally: '+e.message)}}
function active(){return state.worlds.find(w=>w.id===current)}
let connectionState=null, connectionKey=null;
function routingAllowed(w){if(!connectionState)return false;if(connectionState.mode==='client')return !!connectionState.server_id && w?.connectionId===connectionState.server_id;return connectionState.mode==='local'&&!w?.connectionId}
async function routeConnection(connection){connectionState=connection||{mode:'unknown'};const key=connectionState.mode+':'+(connectionState.server_id||'');if(key===connectionKey)return;connectionKey=key;deathDrops=[];observedBuildingKeys.clear();observedRailKeys.clear();observedBaseIds.clear();observedCystKeys.clear();if(connectionState.mode==='client'&&connectionState.server_id&&connectionState.world_name){let w=state.worlds.find(v=>v.connectionId===connectionState.server_id);if(!w){w=state.worlds.find(v=>v.name===connectionState.world_name&&!v.connectionId&&v.mapVersion===2&&!v.image);if(!w){w={id:crypto.randomUUID(),name:connectionState.world_name,image:null,markers:[],mapVersion:2};state.worlds.push(w)}w.connectionId=connectionState.server_id;await persist()}current=w.id;$('resource-detail').hidden=true;refresh();fit()}else if(active())renderBuildings()}
function transform(){$('map').style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;$('map').style.setProperty('--marker-scale',1/scale);$('zoom-label').textContent=Math.round(scale*100)+'%'}
function fit(){const v=$('viewport'),m=$('map');scale=Math.min(v.clientWidth/m.offsetWidth,v.clientHeight/m.offsetHeight)*.96;tx=(v.clientWidth-m.offsetWidth*scale)/2;ty=(v.clientHeight-m.offsetHeight*scale)/2;transform()}
function refresh(){let w=active();$('world').replaceChildren(...state.worlds.map(x=>{let o=document.createElement('option');o.value=x.id;o.textContent=x.name;return o}));$('world').value=current;$('world-title').textContent=w.name;if(imageURL){URL.revokeObjectURL(imageURL);imageURL=null}const img=$('background');if(w.image){imageURL=URL.createObjectURL(w.image);img.src=imageURL;img.style.display='block';$('placeholder').style.display='none';$('map-status').textContent='LOCAL MAP IMAGE'}else{img.src=w.mapVersion===2?(w.radiationLevel===1?'terrain-map-r2.jpg':'terrain-map.jpg'):'game-map.png';img.style.display='block';$('placeholder').style.display='none';$('map-status').textContent=w.mapVersion===2?(w.radiationLevel===1?'GAME TERRAIN · EXPANDED RADIATION BOUNDARY':w.radiationLevel===0?'GAME TERRAIN · STARTER RADIATION BOUNDARY':'GAME TERRAIN · RADIATION STATE UNKNOWN'):'EARLIER QA MAP · MARKERS PRESERVED'}renderRadiation();renderMarkers();renderResources();renderLandmarks();renderBuildings();renderRails();renderBaseCysts();renderShared();renderInfectionAreas();renderOtherPlayers();renderDeathDrops()}
function renderMarkers(){const w=active(),q=$('search').value.toLowerCase();$('count').textContent=w.markers.length;$('pins').replaceChildren();$('list').replaceChildren();const matching=w.markers.filter(m=>(m.name+' '+m.note).toLowerCase().includes(q));if(!matching.length){let e=document.createElement('p');e.className='empty';e.textContent=w.markers.length?'No matching places.':'No markers yet. Add one to remember a place.';$('list').append(e)}for(const m of matching){const c=colors[m.color]||colors.amber,p=document.createElement('button');p.className='pin';p.style.setProperty('--c',c);p.style.left=(m.x*100)+'%';p.style.top=(m.y*100)+'%';p.title=m.name;p.setAttribute('aria-label','Edit '+m.name);p.innerHTML='<span>•</span>';p.onclick=e=>{e.stopPropagation();edit(m)};$('pins').append(p);const item=document.createElement('button');item.className='item';const dot=document.createElement('span');dot.className='swatch';dot.style.setProperty('--c',c);const txt=document.createElement('span'),b=document.createElement('b'),s=document.createElement('small');b.textContent=m.name;s.textContent=m.note||'No note';txt.append(b,s);item.append(dot,txt);item.onclick=()=>edit(m);$('list').append(item)}}
function edit(m){selected=m||null;$('editor-title').textContent=m?'Edit marker':'New marker';$('name').value=m?.name||'';$('note').value=m?.note||'';$('color').value=m?.color||'amber';$('delete').hidden=!m;$('editor').showModal();$('name').focus()}
$('form').onsubmit=async e=>{e.preventDefault();const name=$('name').value.trim();if(!name)return;let m=selected||{id:crypto.randomUUID(),...pending};Object.assign(m,{name,note:$('note').value,color:$('color').value});if(!selected)active().markers.push(m);await persist();$('editor').close();pending=null;renderMarkers()};$('close').onclick=()=>$('editor').close();$('delete').onclick=async()=>{if(!selected||!confirm('Delete this marker?'))return;active().markers=active().markers.filter(m=>m.id!==selected.id);await persist();$('editor').close();renderMarkers()};
$('add').onclick=()=>{$('placing-text').textContent='Click anywhere on the map to place your marker';placing=true;$('placing').hidden=false};$('cancel-place').onclick=()=>{placing=false;$('placing').hidden=true};
$('image-btn').onclick=$('placeholder-image').onclick=()=>$('image').click();$('image').onchange=async e=>{let f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)){alert('Choose a PNG, JPEG, or WebP image.');return}if(active().markers.length&&!confirm('Replacing the image can move your markers relative to map features. Continue?'))return;active().image=f;await persist();refresh();e.target.value=''};
$('new-world').onclick=async()=>{let name=prompt('Name this world:');if(!name?.trim())return;let w={id:crypto.randomUUID(),name:name.trim().slice(0,100),image:null,markers:[],mapVersion:2};state.worlds.push(w);current=w.id;await persist();refresh();fit()};$('world').onchange=e=>{$('resource-detail').hidden=true;current=e.target.value;observedBuildingKeys.clear();observedRailKeys.clear();observedBaseIds.clear();observedCystKeys.clear();placing=false;$('placing').hidden=true;refresh();fit();drawPlayer()};$('search').oninput=renderMarkers;
$('viewport').addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.target.closest('#placeholder'))return;if(placing){const r=$('map').getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;if(x<0||x>1||y<0||y>1)return;pending={x,y};placing=false;$('placing').hidden=true;edit(null);return}drag={x:e.clientX,y:e.clientY,tx,ty};$('viewport').setPointerCapture(e.pointerId)});$('viewport').addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>3)setFollowing(false);tx=drag.tx+e.clientX-drag.x;ty=drag.ty+e.clientY-drag.y;transform()});$('viewport').addEventListener('pointerup',()=>drag=null);$('viewport').addEventListener('pointercancel',()=>drag=null);
function zoom(f,x,y){const v=$('viewport').getBoundingClientRect();x=x??v.width/2;y=y??v.height/2;const next=Math.min(20,Math.max(.1,scale*f));tx=x-(x-tx)*next/scale;ty=y-(y-ty)*next/scale;scale=next;transform()}$('viewport').addEventListener('wheel',e=>{e.preventDefault();const r=$('viewport').getBoundingClientRect();zoom(e.deltaY<0?1.15:1/1.15,e.clientX-r.left,e.clientY-r.top)},{passive:false});$('zoom-in').onclick=()=>zoom(1.2);$('zoom-out').onclick=()=>zoom(1/1.2);$('fit').onclick=()=>{setFollowing(false);fit()};
$('export').onclick=async()=>{const worlds=await Promise.all(state.worlds.map(async w=>({...w,image:w.image?await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(w.image)}):null})));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,worlds,sharedKnown:state.sharedKnown})],{type:'application/json'}));a.download='rupture-map-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('import-btn').onclick=()=>$('import').click();$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const data=JSON.parse(await f.text());if(data.version!==1||!Array.isArray(data.worlds)||!data.worlds.length)throw Error('Invalid backup');const worlds=[];for(const w of data.worlds){if(typeof w.name!=='string'||!Array.isArray(w.markers)||w.markers.some(m=>typeof m.name!=='string'||typeof m.note!=='string'||!Number.isFinite(m.x)||!Number.isFinite(m.y)||m.x<0||m.x>1||m.y<0||m.y>1))throw Error('Invalid world or marker');let image=null;if(w.image){if(typeof w.image!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(w.image))throw Error('Invalid image');image=await (await fetch(w.image)).blob()}worlds.push({id:crypto.randomUUID(),name:w.name.slice(0,100),image,mapVersion:w.mapVersion===2?2:1,infectionAreas:Array.isArray(w.infectionAreas)?w.infectionAreas.filter(InfectionAreas.valid).slice(0,2000):[],rails:Array.isArray(w.rails)?w.rails.filter(validRail).slice(0,10000):[],bases:Array.isArray(w.bases)?w.bases.filter(validBase).slice(0,1000):[],cysts:Array.isArray(w.cysts)?w.cysts.filter(validCyst).slice(0,10000):[],radiationLevel:w.radiationLevel===0||w.radiationLevel===1?w.radiationLevel:null,connectionId:typeof w.connectionId==='string'&&/^[a-f0-9]{64}$/.test(w.connectionId)?w.connectionId:null,landmarks:Array.isArray(w.landmarks)?w.landmarks.filter(v=>typeof v.id==='string'&&typeof v.name==='string'&&Number.isFinite(v.x)&&Number.isFinite(v.y)).slice(0,1000):[],resources:Array.isArray(w.resources)?w.resources.filter(r=>typeof r.type==='string'&&typeof r.key==='string'&&Number.isFinite(r.x)&&Number.isFinite(r.y)).slice(0,5000):[],buildings:Array.isArray(w.buildings)?w.buildings.filter(r=>isStandaloneBuilding(r)&&typeof r.type==='string'&&typeof r.key==='string'&&typeof r.category==='string'&&Number.isFinite(r.x)&&Number.isFinite(r.y)).slice(0,10000):[],markers:w.markers.map(m=>({...m,id:crypto.randomUUID()}))})}if(!confirm('Import these worlds alongside your existing worlds?'))return;state.sharedKnown=SharedKnown.merge(state.sharedKnown,[{...data.sharedKnown,mapVersion:2,image:null}]);state.worlds.push(...worlds);current=worlds[0].id;await persist();refresh();fit()}catch(err){alert('Could not import backup: '+err.message)}finally{e.target.value=''}};
(async()=>{try{const saved=await read();if(saved?.version===1&&saved.worlds?.length)state=saved;for(const w of state.worlds){if(w.buildings)w.buildings=w.buildings.filter(isStandaloneBuilding);if(!w.mapVersion)w.mapVersion=w.markers.length?1:2;if(w.resources){const named=w.resources.filter(r=>r.type.endsWith(' deposit'));w.resources=w.resources.filter(r=>r.type!=='Ore deposit (type unknown)'||!named.some(v=>Math.hypot(v.x-r.x,v.y-r.y)<50))}}if(!state.worlds.some(w=>w.mapVersion===2&&!w.image)){state.worlds.push({id:crypto.randomUUID(),name:'Live map',image:null,markers:[],mapVersion:2})}current=state.worlds.find(w=>w.mapVersion===2&&!w.image).id;$('show-undiscovered').checked=state.showUndiscovered!==false;setNotesCollapsed(state.notesCollapsed===true,false);$('show-infection-areas').checked=state.infectionAreasEnabled!==false;$('show-bases').checked=state.basesEnabled!==false;$('show-cysts').checked=state.cystsEnabled!==false;$('show-death-drops').checked=state.deathDropsEnabled!==false;$('show-other-players').checked=state.otherPlayersEnabled!==false;$('show-rails').checked=state.railsEnabled!==false;$('show-buildings').checked=state.buildingsEnabled!==false;$('show-old-buildings').checked=state.showOldBuildings!==false;$('show-objectives').checked=state.objectivesEnabled!==false;$('objective-panel').hidden=!$('show-objectives').checked;await persist();refresh();fit()}catch(e){alert('Local storage is unavailable: '+e.message)}})();

function drawPlayer(){const el=$('player'),w=active();if(!live||!w||w.image||w.mapVersion!==2){el.hidden=true;return}const px=(live.x+480000)/600000,py=(live.y+380000)/600000;if(!Number.isFinite(px)||!Number.isFinite(py)||px<0||px>1||py<0||py>1){el.hidden=true;return}el.style.left=(100*px)+'%';el.style.top=(100*py)+'%';el.classList.toggle('has-heading',Number.isFinite(live.yaw));if(Number.isFinite(live.yaw))el.style.setProperty('--heading',live.yaw+'deg');el.hidden=false;if(following){if(!followInitialized){scale=Math.max(scale,1.5);followInitialized=true}const view=$('viewport'),map=$('map');tx=view.clientWidth/2-px*map.offsetWidth*scale;ty=view.clientHeight/2-py*map.offsetHeight*scale;transform()}}
function setFollowing(enabled){following=enabled;$('follow').textContent=enabled?'◉ Following':'◎ Follow me';$('follow').setAttribute('aria-pressed',String(enabled))}
$('follow').onclick=()=>{setFollowing(!following);if(following){followInitialized=false;drawPlayer()}};
let positionRunning=false;
async function pollPosition(){if(positionRunning)return;positionRunning=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),6000);try{const res=await fetch('/api/position',{cache:'no-store',signal:controller.signal});const data=await res.json();if(!data.ok)throw Error(data.error);await routeConnection(data.connection);await updateRadiation(data.radiation_level);updateWave(data.wave,data.connection);live=data;updateOtherPlayers(data.other_players);$('tracking-status').className='status online';$('tracking-status').innerHTML='<span class="dot"></span> '+(active().mapVersion===2&&!active().image?(routingAllowed(active())?'Live position connected':'Live position connected · discoveries paused for this world'):'Live position available on the game terrain map');drawPlayer()}catch(e){updateWave(null);connectionState=null;connectionKey=null;live=null;updateOtherPlayers(null);$('player').hidden=true;$('tracking-status').className='status';$('tracking-status').textContent='Tracking unavailable: '+e.message}finally{clearTimeout(timeout);positionRunning=false}}
setInterval(pollPosition,1000);setTimeout(pollPosition,200);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollPosition()});
window.addEventListener('focus',()=>pollPosition());

const resourceColors={'Dead Body (foundable)':'#e2c1a4','Drone Wreck':'#e6c590','Meteorite':'#ffcb80','Vulpir Egg':'#ffd6c1','Coralion Egg':'#aee0ff','Grubbler':'#f5c678','Glowcap':'#dbadff','Calcium chunk':'#e8e4c3','Titanium chunk':'#89cfff','Wolfram chunk':'#eea47f','Helium-3 chunk':'#cc9bfc','Ignitium':'#ff9672','Quartz':'#d5f6ff','Hydrobulb':'#55d9eb','Polifruit':'#ffb165','Oxallop':'#ed93bf','Purplant':'#d2a1ff','Serpent Root':'#a9d875','Prickler':'#f5d877','Prism Herb':'#a6d7ff','Sulheart':'#ffa489','Star Tears':'#f8e8ac','Calcium deposit':'#e8e4c3','Titanium deposit':'#89cfff','Wolfram deposit':'#eea47f','Sulphur deposit':'#f1de70','Helium-3 deposit':'#cc9bfc','Goethite deposit':'#d9ab6c','Ore deposit (type unknown)':'#b5bed3'};
const materialIcons={'Dead Body (foundable)':'\ue7fd','Drone Wreck':'\uf06c','Meteorite':'\ue3a5','Hydrobulb':'\ue798','Polifruit':'\ue545','Oxallop':'\uea35','Purplant':'\ue3e3','Serpent Root':'\uf205','Prickler':'\ueb4c','Prism Herb':'\uea35','Sulheart':'\ue3e3','Star Tears':'\ue3e4','Grubbler':'\uea99','Glowcap':'\ue545','Vulpir Egg':'\ueacc','Coralion Egg':'\ueacc','Calcium deposit':'\uead5','Titanium deposit':'\uead5','Wolfram deposit':'\uead5','Goethite deposit':'\uead5','Sulphur deposit':'\uebda','Helium-3 deposit':'\ue6dd','Ore deposit (type unknown)':'\ue564','Calcium chunk':'\ue3ea','Titanium chunk':'\ue3ea','Wolfram chunk':'\ue3ea','Helium-3 chunk':'\ue6dd','Ignitium':'\ue80e','Quartz':'\uead5'};
function resourceIcon(type){const icon=document.createElement('span');icon.className='material-icon';icon.setAttribute('aria-hidden','true');if(type==='Polifruit'){icon.classList.add('corn-icon');icon.innerHTML='<svg viewBox="0 0 24 24" focusable="false"><path d="M12 2C8.7 2 6.5 5.1 6.5 9.3c0 2.6.7 5.1 2 7.1C5.7 15.6 4.1 13.6 3 11.4 2.8 17.1 6 21 12 22c6-1 9.2-4.9 9-10.6-1.1 2.2-2.7 4.2-5.5 5 1.3-2 2-4.5 2-7.1C17.5 5.1 15.3 2 12 2Z" fill="currentColor"/><path d="M9 6h1m3 0h1M8.7 9h1m3.3 0h1M9 12h1m3 0h1M10 15h1m2 0h1" stroke="#172421" stroke-width="1.2" stroke-linecap="round"/></svg>'}else icon.textContent=materialIcons[type]||'\uea35';return icon}
function resourceTypeEnabled(type){return state.resourceFilters?.[type]!==false}
function renderResources(){
 const w=active(),target=$('resource-pins'),legend=$('resource-legend');if(!w)return;
 const items=w.resources||[],shared=state.sharedKnown?.resources||[];$('resource-count').textContent=items.length;target.replaceChildren();legend.replaceChildren();
 const types=new Set([...items,...shared].map(r=>r.type));
 for(const type of [...types].sort()){
  const row=document.createElement('label'),input=document.createElement('input'),dot=resourceIcon(type),name=document.createElement('span'),count=document.createElement('b');
  row.className='resource-key';input.type='checkbox';input.checked=resourceTypeEnabled(type);input.disabled=!$('show-resources').checked;dot.classList.add('resource-key-icon');dot.style.color=resourceColors[type]||'#7ccf92';name.textContent=type;count.textContent=items.filter(r=>r.type===type).length;row.append(input,dot,name,count);legend.append(row);
  input.onchange=async()=>{state.resourceFilters={...state.resourceFilters,[type]:input.checked};await persist();renderResources();renderShared()};
 }
 if(!$('show-resources').checked||w.image||w.mapVersion!==2)return;
 for(const r of items){if(!resourceTypeEnabled(r.type))continue;const px=(r.x+480000)/600000,py=(r.y+380000)/600000;if(px<0||px>1||py<0||py>1)continue;const pin=document.createElement('button');pin.type='button';pin.className='resource-pin'+(r.depleted?' depleted':'');pin.style.left=px*100+'%';pin.style.top=py*100+'%';pin.style.setProperty('--resource-color',resourceColors[r.type]||'#7ccf92');pin.title=r.type;pin.setAttribute('aria-label',r.type+(r.depleted?', depleted when last observed':' , availability unknown'));const icon=resourceIcon(r.type);pin.append(icon);pin.onclick=e=>{e.stopPropagation();$('habitat-name-form').hidden=true;$('resource-detail-name').textContent=r.type;$('resource-detail-state').textContent=r.depleted?'Depleted when last observed':'Last observed here · current availability unknown';$('resource-detail').hidden=false};target.append(pin)}
}
$('resource-detail-close').onclick=()=>{$('resource-detail').hidden=true};
$('show-resources').onchange=()=>{renderResources();renderShared()};
$('clear-resources').onclick=async()=>{const w=active();if(!w?.resources?.length)return;if(!confirm('Clear all discovered resources in this world? Nearby resources may be rediscovered.'))return;w.resources=[];await persist();renderResources();renderShared()};
let scanningResources=false;
async function pollResources(){if(scanningResources||!active())return;const w=active();if(!routingAllowed(w)){$('resource-status').textContent='Discoveries paused: select the world for this connection';return}if(w.image||w.mapVersion!==2){$('resource-status').textContent='Discoveries available on the game terrain map';return}scanningResources=true;try{const res=await fetch('/api/resources',{cache:'no-store'}),data=await res.json();if(!data.ok)throw Error(data.error);if(active()!==w||!routingAllowed(w))return;const items=w.resources||(w.resources=[]),byKey=new Map(items.map(r=>[r.key,r]));let changed=false;for(const r of data.resources){if(!Number.isFinite(r.x)||!Number.isFinite(r.y)||typeof r.type!=='string')continue;const key=r.type+':'+Math.round(r.x/100)+':'+Math.round(r.y/100);let prior=byKey.get(key);if(!prior&&r.type.endsWith(' deposit')){prior=items.find(v=>v.type==='Ore deposit (type unknown)'&&Math.hypot(v.x-r.x,v.y-r.y)<50);if(prior){byKey.delete(prior.key);prior.key=key;prior.type=r.type;byKey.set(key,prior);changed=true}}if(prior){if(prior.depleted!==r.depleted){prior.depleted=r.depleted;prior.observed=Date.now();changed=true}}else if(items.length<5000){const entry={key,type:r.type,x:r.x,y:r.y,depleted:r.depleted,observed:Date.now()};items.push(entry);byKey.set(key,entry);changed=true}}if(changed)await persist();if(active()===w){$('resource-status').textContent='Scanning within 100 m · last-known locations';renderResources();renderShared()}}catch(e){if(active()===w)$('resource-status').textContent='Resource scan unavailable: '+e.message}finally{scanningResources=false}}
setInterval(pollResources,10000);setTimeout(pollResources,1500);

let objectivesRunning=false;
function renderLandmarks(){const w=active(),target=$('landmark-pins');target.replaceChildren();if(!w)return;const items=w.landmarks||[];$('landmark-count').textContent=items.length?items.length+' nearby landmarks remembered · not objective destinations':'Nearby landmarks appear as you explore';if(!$('show-objectives').checked||w.image||w.mapVersion!==2)return;for(const r of items){if(r.kind==='abandoned_base')continue;const px=(r.x+480000)/600000,py=(r.y+380000)/600000;if(px<0||px>1||py<0||py>1)continue;const pin=document.createElement('button');pin.type='button';pin.className='landmark-pin';pin.style.left=px*100+'%';pin.style.top=py*100+'%';pin.title=r.name+' · landmark';pin.setAttribute('aria-label',r.name+', landmark');const icon=resourceIcon('landmark');icon.textContent='\ue55f';pin.append(icon);pin.onclick=e=>{e.stopPropagation();$('habitat-name-form').hidden=true;$('resource-detail-name').textContent=r.name;$('resource-detail-state').textContent='Nearby landmark · not necessarily an active objective';$('resource-detail').hidden=false};target.append(pin)}}
function showObjectives(data){const list=$('objective-list');list.replaceChildren();$('objective-status').textContent=data.active.length?data.active.length+' active · '+data.completed+' completed': 'No active tutorial objectives · '+data.completed+' completed';for(const entry of data.active){const box=document.createElement('div');box.className='objective-entry';const title=document.createElement('strong');title.textContent=entry.name;box.append(title);for(const step of entry.steps){const row=document.createElement('div');row.className='objective-step';row.textContent=step.text+(step.current!==null&&step.target!==null&&step.target>0?' ('+step.current+' / '+step.target+')':'');box.append(row)}list.append(box)}}
$('show-objectives').onchange=async()=>{state.objectivesEnabled=$('show-objectives').checked;$('objective-panel').hidden=!state.objectivesEnabled;$('resource-detail').hidden=true;await persist();renderLandmarks();renderShared();if(state.objectivesEnabled)pollObjectives()};
async function pollObjectives(){if(objectivesRunning||!active()||!$('show-objectives').checked)return;const w=active();if(!routingAllowed(w))return;objectivesRunning=true;try{const response=await fetch('/api/objectives',{cache:'no-store'});const data=await response.json();if(!data.ok)throw Error(data.error);if(!$('show-objectives').checked||active()!==w||!routingAllowed(w))return;showObjectives(data);if(!w.image&&w.mapVersion===2){const items=w.landmarks||(w.landmarks=[]),known=new Set(items.map(v=>v.id));let changed=false;for(const v of data.landmarks){if(!known.has(v.id)&&Number.isFinite(v.x)&&Number.isFinite(v.y)&&typeof v.name==='string'){items.push(v);known.add(v.id);changed=true}}if(changed)await persist();renderLandmarks();renderShared()}}catch(e){if($('show-objectives').checked&&active()===w)$('objective-status').textContent='Objectives unavailable: '+e.message}finally{objectivesRunning=false}}
setInterval(pollObjectives,10000);setTimeout(pollObjectives,1800);

function setNotesCollapsed(collapsed,adjust=true){const viewport=$('viewport'),oldWidth=viewport.clientWidth,oldHeight=viewport.clientHeight;document.body.classList.toggle('notes-collapsed',collapsed);$('notes-panel').hidden=collapsed;const button=$('toggle-notes');button.setAttribute('aria-expanded',String(!collapsed));button.textContent=collapsed?'▶ Notes':'◀ Notes';button.title=collapsed?'Show notes panel':'Hide notes panel';if(adjust){requestAnimationFrame(()=>{if(following&&live){drawPlayer()}else{tx+=(viewport.clientWidth-oldWidth)/2;ty+=(viewport.clientHeight-oldHeight)/2;transform()}})}}
