document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('filters-menu').open){$('filters-menu').open=false;$('filters-menu').querySelector('summary').focus()}});
document.addEventListener('pointerdown',e=>{const menu=$('filters-menu');if(menu.open&&!menu.contains(e.target))menu.open=false});

// Building records are local last-known observations, never writes to the game.
const buildingCategories = {Production:['\uea40','#ffc580'],Power:['\ue3a7','#ffe082'],Facilities:['\ue88a','#a4d8ff']};
function isStandaloneBuilding(b){return typeof b?.key==='string' && /^(BP_SolarPowerGenerator_C|BP_HabitatSmall_C|BP_HabitatBig_C|BP_MechanicalDrill_C|BP_Smelter_C|BP_Crafter_C):/.test(b.key)}
let observedBuildingKeys=new Set(), buildingScanRunning=false;
function categoryEnabled(category){return state.buildingFilters?.[category]??!['Structures','Logistics'].includes(category)}
function renderBuildings(){
 $('habitat-tooltip').hidden=true;
 const w=active(),target=$('building-pins'),legend=$('building-categories');target.replaceChildren();legend.replaceChildren();if(!w)return;
 const items=w.buildings||[];$('building-count').textContent=items.length;
 for(const [category,[glyph,color]] of Object.entries(buildingCategories)){
  const label=document.createElement('label'),input=document.createElement('input'),icon=resourceIcon('');input.type='checkbox';input.checked=categoryEnabled(category);input.disabled=!$('show-buildings').checked;icon.textContent=glyph;icon.style.color=color;
  const text=document.createElement('span');text.textContent=category+' ('+items.filter(v=>v.category===category).length+')';label.append(input,icon,text);legend.append(label);
  input.onchange=async()=>{state.buildingFilters={...state.buildingFilters,[category]:input.checked};await persist();renderBuildings()};
 }
 if(!$('show-buildings').checked||w.image||w.mapVersion!==2)return;
 for(const b of items){const observed=observedBuildingKeys.has(b.key);if(!categoryEnabled(b.category)||(!observed&&!$('show-old-buildings').checked))continue;const px=(b.x+480000)/600000,py=(b.y+380000)/600000;if(px<0||px>1||py<0||py>1)continue;
  const [glyph,color]=buildingCategories[b.category]||buildingCategories.Other,pin=document.createElement('button'),icon=resourceIcon('');pin.type='button';pin.className='building-pin'+(observed?'':' last-known');pin.style.left=px*100+'%';pin.style.top=py*100+'%';pin.style.color=color;icon.textContent=glyph;pin.append(icon);
  const status=observed?'Observed by your client in the latest scan':'Last-known location · not currently confirmed',isHabitat=b.type==='Habitat',displayName=isHabitat&&typeof b.customName==='string'&&b.customName.trim()?b.customName:b.type;pin.setAttribute('aria-label',displayName+' · '+status);if(isHabitat){pin.addEventListener('pointermove',e=>{const tip=$('habitat-tooltip');tip.textContent=displayName;tip.hidden=false;const x=Math.min(e.clientX+14,window.innerWidth-tip.offsetWidth-8),y=Math.min(e.clientY+18,window.innerHeight-tip.offsetHeight-8);tip.style.left=Math.max(8,x)+'px';tip.style.top=Math.max(8,y)+'px'});pin.addEventListener('pointerleave',()=>{$('habitat-tooltip').hidden=true})}else pin.title=b.type+' · '+status;pin.onclick=e=>{e.stopPropagation();$('habitat-tooltip').hidden=true;$('resource-detail-name').textContent=displayName;$('resource-detail-state').textContent=(isHabitat&&displayName!==b.type?'Habitat · ':'')+b.category+' · '+status+(b.lastSeen?' · last seen '+new Date(b.lastSeen).toLocaleString():'');const form=$('habitat-name-form');form.hidden=!isHabitat;if(isHabitat){$('habitat-name').value=b.customName||'';form.onsubmit=async e=>{e.preventDefault();b.customName=$('habitat-name').value.trim().slice(0,100);await persist();if(active()===w){$('resource-detail-name').textContent=b.customName||b.type;renderBuildings()}}}$('resource-detail').hidden=false};target.append(pin);
 }
}
$('show-buildings').onchange=async()=>{state.buildingsEnabled=$('show-buildings').checked;observedBuildingKeys.clear();$('resource-detail').hidden=true;await persist();renderBuildings();if(state.buildingsEnabled)pollBuildings()};
$('show-old-buildings').onchange=async()=>{state.showOldBuildings=$('show-old-buildings').checked;await persist();renderBuildings()};
$('clear-buildings').onclick=async()=>{const w=active();if(!w?.buildings?.length||!confirm('Clear remembered buildings in this world? Nearby buildings may be rediscovered.'))return;w.buildings=[];observedBuildingKeys.clear();await persist();renderBuildings()};
async function pollBuildings(){
 if(buildingScanRunning||!active()||!$('show-buildings').checked)return;const w=active();if(!routingAllowed(w)){observedBuildingKeys.clear();$('building-status').textContent='Buildings paused: select the world for this connection';renderBuildings();return}if(w.image||w.mapVersion!==2){observedBuildingKeys.clear();$('building-status').textContent='Buildings available on the game terrain map';renderBuildings();return}buildingScanRunning=true;
 try{const response=await fetch('/api/buildings',{cache:'no-store'}),data=await response.json();if(!data.ok||!Array.isArray(data.buildings))throw Error(data.error||'Invalid scan');if(active()!==w||!$('show-buildings').checked||!routingAllowed(w))return;
  const items=w.buildings||(w.buildings=[]),known=new Map(items.map(b=>[b.key,b])),now=Date.now(),observed=new Set();let changed=false;
  for(const b of data.buildings){if(!isStandaloneBuilding(b)||typeof b.key!=='string'||typeof b.type!=='string'||!buildingCategories[b.category]||!Number.isFinite(b.x)||!Number.isFinite(b.y))continue;observed.add(b.key);const prior=known.get(b.key);if(prior){if(!prior.lastSeen||now-prior.lastSeen>60000){prior.lastSeen=now;changed=true}}else if(items.length<10000){const record={key:b.key,type:b.type,category:b.category,x:b.x,y:b.y,lastSeen:now};items.push(record);known.set(b.key,record);changed=true}}
  observedBuildingKeys=observed;$('building-status').textContent=observed.size+' observed within '+data.radius_m+' m · faded markers are last-known';if(changed)await persist();if(active()===w)renderBuildings();
 }catch(e){if(active()===w){observedBuildingKeys.clear();$('building-status').textContent='Building scan unavailable: '+e.message;renderBuildings()}}finally{buildingScanRunning=false}
}
setTimeout(pollBuildings,5000);setInterval(pollBuildings,10000);

// Changes are saved immediately; this also checkpoints state every 30 seconds.
setInterval(()=>{if(current)persist()},30000);

let waveSnapshot=null, lastWaveClock=null, waveClockChanged=0, waveLastSample=0, waveUnchangedSamples=0;
function updateWave(data){
 const now=performance.now();
 if(!data||!Number.isFinite(data.seconds)||!Number.isFinite(data.clock)||!Number.isFinite(data.deadline)){waveSnapshot=null;lastWaveClock=null;waveLastSample=0;waveUnchangedSamples=0;drawWave();return}
 const freshClock=lastWaveClock===null||Math.abs(data.clock-lastWaveClock)>.001;
 const reset=!waveSnapshot||data.deadline!==waveSnapshot.deadline||data.phase!==waveSnapshot.phase||data.paused!==waveSnapshot.paused;
 // A long gap between browser samples is not evidence that the game clock stopped.
 if(freshClock||reset||!waveLastSample||now-waveLastSample>3500){waveClockChanged=now;waveUnchangedSamples=0}
 else waveUnchangedSamples++;
 waveLastSample=now;
 let seconds=data.seconds;
 // Ignore tiny backwards clock corrections that would make displayed seconds twitch.
 // Larger corrections or a new phase remain visible instead of hiding real changes.
 if(!reset&&seconds>waveSnapshot.seconds&&seconds-waveSnapshot.seconds<=2)seconds=waveSnapshot.seconds;
 lastWaveClock=data.clock;waveSnapshot={...data,seconds,received:now};drawWave();
}
function drawWave(){
 const out=$('wave-time'),tip=$('wave-timer'),viewport=$('viewport'),now=performance.now();
 viewport.classList.remove('wave-warning','wave-critical');$('wave-frequency').textContent='WF: '+(waveSnapshot?.frequency||'Unknown');tip.querySelector('span').textContent='RUPTURE · NEXT PHASE';
 if(!waveSnapshot||now-waveSnapshot.received>6000){out.textContent='Unavailable';tip.title='Wave timer is unavailable';return}
 if(waveSnapshot.paused){out.textContent='Paused';tip.title='The game reports the wave timer is paused';return}
 if(waveUnchangedSamples>=3&&waveLastSample-waveClockChanged>5000){tip.querySelector('span').textContent='RUPTURE · CLOCK NOT UPDATING';tip.title='The game clock has stopped updating. Showing the last confirmed time.'}
 else tip.title='Time until the next reported wave phase; this is not necessarily the fire-wave impact';
 const seconds=Math.max(0,Math.ceil(waveSnapshot.seconds));
 if(seconds===0){out.textContent='Awaiting update';tip.title='Waiting for the game to report the next phase';return}
 const hours=Math.floor(seconds/3600),minutes=Math.floor(seconds%3600/60),secs=seconds%60;out.textContent=(hours?hours+':'+String(minutes).padStart(2,'0'):String(minutes))+':'+String(secs).padStart(2,'0');
 if(seconds<=300)viewport.classList.add('wave-warning');if(seconds<=120)viewport.classList.add('wave-critical');
}
setInterval(drawWave,1000);

// Actual spline segments, stored separately in each local world.
let observedRailKeys=new Set(), railScanRunning=false;
function validRail(r){return typeof r?.key==='string'&&r.key.startsWith('ziprail:')&&Array.isArray(r.points)&&r.points.length>=2&&r.points.length<=249&&r.points.every(p=>Array.isArray(p)&&p.length===3&&p.every(v=>Number.isFinite(v)&&Math.abs(v)<1e7))}
function renderRails(){const target=$('rail-paths'),w=active();target.replaceChildren();if(!w)return;const items=(w.rails||[]).filter(validRail);$('rail-count').textContent=items.length;if(!$('show-rails').checked||w.image||w.mapVersion!==2)return;for(const route of items){const path=document.createElementNS('http://www.w3.org/2000/svg','polyline');path.setAttribute('points',route.points.map(p=>((p[0]+480000)/600000*1200)+','+((p[1]+380000)/600000*1200)).join(' '));path.setAttribute('class',observedRailKeys.has(route.key)?'rail-current':'rail-last-known');target.append(path)}}
$('show-rails').onchange=async()=>{state.railsEnabled=$('show-rails').checked;observedRailKeys.clear();await persist();renderRails();if(state.railsEnabled)pollRails()};
$('clear-rails').onclick=async()=>{const w=active();if(!w?.rails?.length||!confirm('Clear remembered zip-rail routes in this world? Nearby routes may be rediscovered.'))return;w.rails=[];observedRailKeys.clear();await persist();renderRails()};
async function pollRails(){if(railScanRunning||!active()||!$('show-rails').checked)return;const w=active();if(!routingAllowed(w)){observedRailKeys.clear();$('rail-status').textContent='Routes paused: select the world for this connection';renderRails();return}if(w.image||w.mapVersion!==2){observedRailKeys.clear();$('rail-status').textContent='Routes available on the game terrain map';renderRails();return}railScanRunning=true;try{const response=await fetch('/api/rails',{cache:'no-store'}),data=await response.json();if(!data.ok||!Array.isArray(data.routes))throw Error(data.error||'Invalid scan');if(active()!==w||!$('show-rails').checked||!routingAllowed(w))return;const items=w.rails||(w.rails=[]),known=new Map(items.map(v=>[v.key,v])),observed=new Set();let changed=false;for(const r of data.routes){if(!validRail(r))continue;observed.add(r.key);const previous=known.get(r.key);if(!previous&&items.length<10000){const entry={key:r.key,points:r.points};items.push(entry);known.set(r.key,entry);changed=true}else if(previous&&JSON.stringify(previous.points)!==JSON.stringify(r.points)){previous.points=r.points;changed=true}}observedRailKeys=observed;$('rail-status').textContent=observed.size+' nearby · solid observed, dashed last-known';if(changed)await persist();if(active()===w)renderRails()}catch(e){if(active()===w){observedRailKeys.clear();$('rail-status').textContent='Route scan unavailable: '+e.message;renderRails()}}finally{railScanRunning=false}}
setTimeout(pollRails,3500);setInterval(pollRails,10000);

// The base records are replicated by the game; cyst actors are observations.
let baseScanRunning=false, observedBaseIds=new Set(), observedCystKeys=new Set();
const baseCategories=[['foundables','Foundables'],['blueprints','Blueprint chests'],['story','Story items'],['cysts','Infection cysts destroyed']];
function validBase(b){return typeof b?.id==='string'&&typeof b.name==='string'&&Number.isFinite(b.x)&&Number.isFinite(b.y)&&b.counts&&baseCategories.every(([k])=>Number.isInteger(b.counts[k]?.collected)&&Number.isInteger(b.counts[k]?.total)&&b.counts[k].collected>=0&&b.counts[k].collected<=b.counts[k].total&&b.counts[k].total<=500)}
function validCyst(c){return typeof c?.key==='string'&&Number.isFinite(c.x)&&Number.isFinite(c.y)&&Math.abs(c.x)<1e7&&Math.abs(c.y)<1e7&&(c.destroyed===true||c.destroyed===false||c.destroyed===null)}
function baseDescription(b){return baseCategories.map(([k,label])=>label+': '+b.counts[k].collected+'/'+b.counts[k].total).join('\n')}
function renderBaseCysts(){
 $('base-tooltip').hidden=true;const w=active(),baseTarget=$('base-pins'),cystTarget=$('cyst-pins');baseTarget.replaceChildren();cystTarget.replaceChildren();if(!w)return;const bases=(w.bases||[]).filter(validBase),cysts=(w.cysts||[]).filter(validCyst);$('base-count').textContent=bases.length;$('cyst-count').textContent=cysts.length;if(w.image||w.mapVersion!==2)return;
 if($('show-bases').checked)for(const b of bases){const px=(b.x+480000)/600000,py=(b.y+380000)/600000;if(px<0||px>1||py<0||py>1)continue;const pin=document.createElement('button'),icon=resourceIcon('');pin.type='button';pin.className='base-pin'+(observedBaseIds.has(b.id)?'':' last-known');pin.style.left=px*100+'%';pin.style.top=py*100+'%';icon.textContent='\ue7f1';pin.append(icon);const info=baseDescription(b),status=observedBaseIds.has(b.id)?'Latest scan':'Last recorded; current status unknown';pin.setAttribute('aria-label',b.name+', '+info.replaceAll('\n',', ')+', '+status);pin.addEventListener('pointermove',e=>{const tip=$('base-tooltip');tip.textContent=b.name+'\n'+info+'\n'+status;tip.hidden=false;tip.style.left=Math.max(8,Math.min(e.clientX+14,window.innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.max(8,Math.min(e.clientY+18,window.innerHeight-tip.offsetHeight-8))+'px'});pin.addEventListener('pointerleave',()=>{$('base-tooltip').hidden=true});pin.onclick=e=>{e.stopPropagation();$('base-tooltip').hidden=true;$('habitat-name-form').hidden=true;$('resource-detail-name').textContent=b.name;$('resource-detail-state').textContent=info+'\n'+status;$('resource-detail').hidden=false};baseTarget.append(pin)}
 if($('show-cysts').checked)for(const c of cysts){const px=(c.x+480000)/600000,py=(c.y+380000)/600000;if(px<0||px>1||py<0||py>1)continue;const pin=document.createElement('button'),icon=resourceIcon('');const observed=observedCystKeys.has(c.key),status=c.confirmedByBase?(c.destroyed?'Destroyed · last reported by base':'Not destroyed · last reported by base'):c.destroyed===true?'Destroyed when last observed':c.destroyed===false?(observed?'Observed in the latest scan':'Last observed here; current status unknown'):'Last observed here; destruction status unknown';pin.type='button';pin.className='cyst-pin'+(!observed||c.destroyed?' last-known':'');pin.style.left=px*100+'%';pin.style.top=py*100+'%';icon.textContent='\uf221';pin.append(icon);pin.title='Infection cyst · '+status;pin.setAttribute('aria-label',pin.title);pin.onclick=e=>{e.stopPropagation();$('habitat-name-form').hidden=true;$('resource-detail-name').textContent='Infection cyst';$('resource-detail-state').textContent=status;$('resource-detail').hidden=false};cystTarget.append(pin)}
}
$('show-bases').onchange=async()=>{state.basesEnabled=$('show-bases').checked;observedBaseIds.clear();await persist();renderBaseCysts();renderShared();if(state.basesEnabled)pollBaseCysts()};
$('show-cysts').onchange=async()=>{state.cystsEnabled=$('show-cysts').checked;observedCystKeys.clear();await persist();renderBaseCysts();renderShared();if(state.cystsEnabled)pollBaseCysts()};
$('clear-cysts').onclick=async()=>{const w=active();if(!w?.cysts?.length||!confirm('Clear remembered infection cysts in this world? Loaded cysts may be rediscovered.'))return;w.cysts=[];observedCystKeys.clear();await persist();renderBaseCysts();renderShared()};
async function pollBaseCysts(){if(baseScanRunning||!active()||(!$('show-bases').checked&&!$('show-cysts').checked))return;const w=active();if(!routingAllowed(w)){observedBaseIds.clear();observedCystKeys.clear();$('base-status').textContent='Paused: select the world for this connection';$('cyst-status').textContent='Paused: select the world for this connection';renderBaseCysts();return}if(w.image||w.mapVersion!==2){$('base-status').textContent='Available on the game terrain map';$('cyst-status').textContent='Available on the game terrain map';return}baseScanRunning=true;try{const response=await fetch('/api/bases',{cache:'no-store'}),data=await response.json();if(!data.ok)throw Error(data.error||'Scan unavailable');if(active()!==w||!routingAllowed(w))return;let changed=false;const now=Date.now();
  if($('show-bases').checked){if(Array.isArray(data.bases)){const items=w.bases||(w.bases=[]),byId=new Map(items.map(v=>[v.id,v])),observed=new Set();for(const b of data.bases){if(!validBase(b))continue;observed.add(b.id);const old=byId.get(b.id);if(!old){items.push({...b,lastSeen:now});changed=true}else if(JSON.stringify(old.counts)!==JSON.stringify(b.counts)||old.name!==b.name||old.x!==b.x||old.y!==b.y||!old.lastSeen||now-old.lastSeen>60000){Object.assign(old,b,{lastSeen:now});changed=true}}observedBaseIds=observed;$('base-status').textContent=observed.size+' bases · hover for completion'}else{observedBaseIds.clear();$('base-status').textContent='Base data unavailable: '+(data.base_error||'unknown error')}}
  if($('show-cysts').checked){if(Array.isArray(data.cysts)){const items=w.cysts||(w.cysts=[]),known=new Map(items.map(v=>[v.key,v])),observed=new Set();for(const c of data.cysts){if(!validCyst(c))continue;observed.add(c.key);const old=known.get(c.key);if(!old&&items.length<10000){const v={...c,lastSeen:now};items.push(v);known.set(v.key,v);changed=true}else if(old&&(old.destroyed!==c.destroyed||old.x!==c.x||old.y!==c.y||!old.lastSeen||now-old.lastSeen>60000)){Object.assign(old,c,{lastSeen:now});changed=true}}if(data.cyst_status&&typeof data.cyst_status==='object')for(const c of items){const value=data.cyst_status[c.key],confirmed=typeof value==='boolean';if(confirmed&&(c.destroyed!==value||!c.confirmedByBase)){c.destroyed=value;c.confirmedByBase=true;changed=true}else if(!confirmed&&c.confirmedByBase){c.confirmedByBase=false;changed=true}}observedCystKeys=observed;$('cyst-status').textContent=observed.size+' loaded · faded markers are last-known or destroyed'}else{observedCystKeys.clear();$('cyst-status').textContent='Cyst scan unavailable: '+(data.cyst_error||'unknown error')}}
  if(changed)await persist();if(active()===w){renderBaseCysts();renderShared()}
 }catch(e){if(active()===w){observedBaseIds.clear();observedCystKeys.clear();$('base-status').textContent='Base scan unavailable: '+e.message;$('cyst-status').textContent='Cyst scan unavailable: '+e.message;renderBaseCysts()}}finally{baseScanRunning=false}}
setTimeout(pollBaseCysts,2500);setInterval(pollBaseCysts,10000);

// Shared pins contain no world-specific progress, depletion, or player-made objects.
function renderShared(){
 const target=$('shared-pins'),w=active();target.replaceChildren();if(!w||w.image||w.mapVersion!==2||!$('show-undiscovered').checked)return;
 const config=[['resources','show-resources','resource-pin'],['bases','show-bases','base-pin'],['cysts','show-cysts','cyst-pin'],['landmarks','show-objectives','landmark-pin']];
 for(const [kind,toggle,cls] of config){if(!$(toggle).checked)continue;for(const r of SharedKnown.undiscovered(state.sharedKnown,w,kind)){
  if(kind==='resources'&&!resourceTypeEnabled(r.type))continue;const px=(r.x+480000)/600000,py=(r.y+380000)/600000;if(px<0||px>1||py<0||py>1)continue;
  const name=kind==='resources'?r.type:kind==='cysts'?'Infection cyst':r.name,pin=document.createElement('button'),icon=resourceIcon(kind==='resources'?r.type:'');pin.type='button';pin.className=cls+' shared-undiscovered';pin.style.left=px*100+'%';pin.style.top=py*100+'%';
  if(kind==='resources')pin.style.setProperty('--resource-color',resourceColors[r.type]||'#7ccf92');else icon.textContent=kind==='bases'?'\ue7f1':kind==='cysts'?'\uf221':'\ue55f';
  pin.title=name+' · known from the shared map; not discovered here';pin.setAttribute('aria-label',pin.title);pin.append(icon);
  pin.onclick=e=>{e.stopPropagation();$('habitat-name-form').hidden=true;$('resource-detail-name').textContent=name;$('resource-detail-state').textContent='Known from the shared map · not discovered in this world. Current availability and progress are unknown.';$('resource-detail').hidden=false};target.append(pin);
 }}
}
$('show-undiscovered').onchange=async()=>{state.showUndiscovered=$('show-undiscovered').checked;await persist();renderShared()};

function renderRadiation(){const w=active(),known=w?.radiationLevel===0||w?.radiationLevel===1;const indicator=$('world-radiation'),description=known?'Radiation level '+w.radiationLevel:'Radiation level unknown';indicator.hidden=!!w?.image||w?.mapVersion!==2;indicator.setAttribute('aria-label',description);indicator.title=description;$('world-radiation-level').textContent=known?String(w.radiationLevel):'?';$('radiation-state').value=known?String(w.radiationLevel):'unknown';$('radiation-state').disabled=!!w?.image||w?.mapVersion!==2;$('radiation-status').textContent=known?'Last saved for this world · live game readings update it automatically':'Unknown · starter artwork shown for reference, not a confirmed boundary'}
async function updateRadiation(level){const w=active();if(!w||w.image||w.mapVersion!==2||!routingAllowed(w)||(level!==0&&level!==1)||w.radiationLevel===level)return;w.radiationLevel=level;await persist();if(active()===w)refresh()}
$('radiation-state').onchange=async()=>{const w=active();if(!w)return;const value=$('radiation-state').value;w.radiationLevel=value==='0'?0:value==='1'?1:null;await persist();refresh()};

// Observations are an approximate footprint; they are stored per world only.
let infectionPollRunning=false, infectionOutside=null;
function renderInfectionAreas(){
 const w=active(),svg=$('infection-areas');svg.replaceChildren();if(!w)return;
 const areas=(w.infectionAreas||[]).filter(a=>InfectionAreas.valid(a)&&!a.cleared);$('infection-area-count').textContent=areas.length;
 if(!$('show-infection-areas').checked||w.image||w.mapVersion!==2)return;
 const ns='http://www.w3.org/2000/svg',coord=p=>[(p.x+480000)/500,(p.y+380000)/500];
 for(const area of areas){const group=document.createElementNS(ns,'g');group.setAttribute('class','infection-observation');
  for(let i=0;i<area.points.length;i++){const p=area.points[i],a=coord(p);const neighbors=area.points.slice(0,i).map(q=>({q,d:Math.hypot(p.x-q.x,p.y-q.y)})).filter(v=>v.d<=InfectionAreas.LINK).sort((a,b)=>a.d-b.d).slice(0,3);for(const {q} of neighbors){const b=coord(q),line=document.createElementNS(ns,'line');line.setAttribute('x1',a[0]);line.setAttribute('y1',a[1]);line.setAttribute('x2',b[0]);line.setAttribute('y2',b[1]);group.append(line)}const circle=document.createElementNS(ns,'circle');circle.setAttribute('cx',a[0]);circle.setAttribute('cy',a[1]);circle.setAttribute('r','2');group.append(circle)}svg.append(group)
 }
}
$('show-infection-areas').onchange=async()=>{state.infectionAreasEnabled=$('show-infection-areas').checked;await persist();renderInfectionAreas()};
async function pollInfectionAreas(){
 if(infectionPollRunning||!active())return;const w=active();if(!routingAllowed(w)||w.image||w.mapVersion!==2){infectionOutside=null;return}
 infectionPollRunning=true;const sample=live;try{
  const response=await fetch('/api/infection-hud',{cache:'no-store',signal:AbortSignal.timeout(5000)}),hud=await response.json();
  if(!hud.ok||!hud.available||active()!==w||!routingAllowed(w)||!sample||!Number.isFinite(sample.x)||!Number.isFinite(sample.y)||Date.now()-sample.time*1000>5000){infectionOutside=null;$('infection-area-status').textContent='Tracker unavailable · remembered areas preserved';return}
  const point={x:sample.x,y:sample.y},areas=w.infectionAreas||(w.infectionAreas=[]);let changed=false;
  if(hud.active&&Number.isInteger(hud.tumors)&&hud.tumors>0){infectionOutside=null;changed=InfectionAreas.observe(areas,point);$('infection-area-status').textContent=hud.tumors+' tumors remaining · recording nearby observations'}
  else if(hud.active&&hud.tumors===0){infectionOutside=null;changed=InfectionAreas.clearNearby(areas,point);$('infection-area-status').textContent='No tumors · nearby observations cleared'}
  else if(hud.active===false&&InfectionAreas.nearby(areas,point)&&!document.hidden){
   const now=performance.now();if(!infectionOutside||infectionOutside.world!==w.id||Math.hypot(point.x-infectionOutside.point.x,point.y-infectionOutside.point.y)>150)infectionOutside={world:w.id,point,since:now,samples:1};else infectionOutside.samples++;
   if(infectionOutside.samples>=4&&now-infectionOutside.since>=10000){changed=InfectionAreas.clearNearby(areas,point);infectionOutside=null;$('infection-area-status').textContent='No tracker while stationary · nearby observations cleared'}else $('infection-area-status').textContent='Checking whether this observed area is clear…';
  }else{infectionOutside=null;$('infection-area-status').textContent='No active tumor tracker · remembered areas preserved'}
  if(changed){await persist();if(active()===w)renderInfectionAreas()}
 }catch(e){infectionOutside=null;if(active()===w)$('infection-area-status').textContent='Tracker unavailable · remembered areas preserved'}finally{infectionPollRunning=false}
}
setTimeout(pollInfectionAreas,3000);setInterval(pollInfectionAreas,2000);

let otherPlayerSamples=new Map();
function updateOtherPlayers(players){
 const now=Date.now();if(!Array.isArray(players)){otherPlayerSamples.clear();renderOtherPlayers();return}
 const next=new Map();for(const p of players){if(typeof p.name!=='string'||!Number.isFinite(p.x)||!Number.isFinite(p.y))continue;if(!Number.isInteger(p.id))continue;const old=otherPlayerSamples.get(p.id),same=old&&old.x===p.x&&old.y===p.y&&old.yaw===p.yaw;next.set(p.id,{...p,changed:same?old.changed:now})}otherPlayerSamples=next;renderOtherPlayers();
}
function renderOtherPlayers(){
 const target=$('other-player-pins'),w=active();target.replaceChildren();$('other-player-count').textContent=otherPlayerSamples.size;
 $('other-player-status').textContent=otherPlayerSamples.size?'Positions can update intermittently':'No other players reported';
 if(!$('show-other-players').checked||!w||w.image||w.mapVersion!==2||!routingAllowed(w)||connectionState?.mode!=='client')return;
 const prefixCounts=new Map();for(const p of otherPlayerSamples.values()){const prefix=Array.from(p.name).slice(0,3).join('');prefixCounts.set(prefix,(prefixCounts.get(prefix)||0)+1)}
 for(const p of otherPlayerSamples.values()){const px=(p.x+480000)/600000,py=(p.y+380000)/600000;if(px<0||px>1||py<0||py>1)continue;
  const pin=document.createElement('div');pin.className='other-player-pin';pin.style.left=px*100+'%';pin.style.top=py*100+'%';const color=Array.isArray(p.color)&&p.color.length===3?p.color.map(v=>Math.round(Math.min(1,Math.max(0,v))*255)):[110,220,255];pin.style.setProperty('--other-color',`rgb(${color.join(',')})`);
  const unchanged=Date.now()-p.changed>15000,status=unchanged?'position unchanged for over 15 seconds':'latest received position';pin.title=p.name+(p.possibly_local?' · possibly your own marker':'')+' · '+status+(p.flags&4?' · dead':p.flags&2?' · incapacitated':'');pin.setAttribute('aria-label',pin.title);pin.classList.toggle('unchanged',unchanged);
  if(Number.isFinite(p.yaw)){const arrow=document.createElement('span');arrow.className='other-player-arrow';arrow.style.transform=`rotate(${p.yaw}deg)`;arrow.innerHTML='<svg viewBox="0 0 18 16"><path d="M16 8 2 1.5 5 8 2 14.5Z" fill="currentColor" stroke="#102326" stroke-width="2" stroke-linejoin="round"/></svg>';pin.append(arrow)}else{const icon=resourceIcon('');icon.textContent='\ue7fd';pin.append(icon)}const label=document.createElement('span'),prefix=Array.from(p.name).slice(0,3).join('');label.className='other-player-label';label.textContent=prefix+'…'+(prefixCounts.get(prefix)>1?' '+p.id:'');pin.append(label);target.append(pin);
 }
}
$('show-other-players').onchange=async()=>{state.otherPlayersEnabled=$('show-other-players').checked;await persist();renderOtherPlayers()};

let deathDrops=[],deathDropsRunning=false;
function renderDeathDrops(){const target=$('death-drop-pins'),w=active();target.replaceChildren();$('death-drop-count').textContent=deathDrops.length;if(!$('show-death-drops').checked||!w||w.image||w.mapVersion!==2||!routingAllowed(w))return;for(const d of deathDrops){const x=(d.x+480000)/600000,y=(d.y+380000)/600000;if(x<0||x>1||y<0||y>1)continue;const pin=document.createElement('div');pin.className='death-drop-pin';pin.style.left=x*100+'%';pin.style.top=y*100+'%';pin.textContent='☠';pin.title='Player death drop · currently loaded';pin.setAttribute('aria-label',pin.title);target.append(pin)}}
$('show-death-drops').onchange=async()=>{state.deathDropsEnabled=$('show-death-drops').checked;await persist();renderDeathDrops()};
async function pollDeathDrops(){if(deathDropsRunning)return;if(!active()||!routingAllowed(active())){deathDrops=[];renderDeathDrops();return}const w=active();deathDropsRunning=true;try{const response=await fetch('/api/death-drops',{cache:'no-store',signal:AbortSignal.timeout(8000)}),data=await response.json();if(!data.ok||!Array.isArray(data.drops))throw Error(data.error||'Invalid response');if(active()!==w||!routingAllowed(w))return;deathDrops=data.drops.filter(d=>Number.isFinite(d.x)&&Number.isFinite(d.y));$('death-drop-status').textContent='Loaded death drops · location and owner may be unavailable at a distance';renderDeathDrops()}catch(e){deathDrops=[];renderDeathDrops();$('death-drop-status').textContent='Death-drop scan unavailable'}finally{deathDropsRunning=false}}
setTimeout(pollDeathDrops,4000);setInterval(pollDeathDrops,5000);
